SELECT setseed(0.17);
\copy (WITH t AS (SELECT u.id::text AS id, u.subject_area, u.question_text AS q, coalesce(u.option_a,'') oa, coalesce(u.option_b,'') ob, coalesce(u.option_c,'') oc, coalesce(u.option_d,'') od, coalesce(u.option_e,'') oe, row_number() OVER (PARTITION BY u.subject_area ORDER BY random()) rn FROM v_safe_for_beta_unfiltered u WHERE (u.pipeline_metadata::jsonb->'ai_extras'->>'topic_match_quality')='fallback' AND (u.pipeline_metadata::jsonb->>'verified_provisional')='true') SELECT id,subject_area,q,oa,ob,oc,od,oe FROM t WHERE (subject_area='KIMYA' AND rn<=11) OR (subject_area='FIZIK' AND rn<=9) OR (subject_area='BIYOLOJI' AND rn<=8) OR (subject_area='MATEMATIK' AND rn<=8) OR (subject_area='TURKCE' AND rn<=4) OR (subject_area='GEOMETRI' AND rn<=4) OR (subject_area='TARIH' AND rn<=2) OR (subject_area='EDEBIYAT' AND rn<=2) OR (subject_area='SOSYAL' AND rn<=1) OR (subject_area='COGRAFYA' AND rn<=1)) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_vp_unlock/retag_pilot50.csv' WITH (FORMAT csv, HEADER true);
